export * from './useTerminalWriter'

/**
 * How the bytes a terminal receives become the lines it renders.
 *
 * The encoder is chosen when a line is written and decides both how the bytes
 * are grouped into lines and how each line is rendered as text. Lines are
 * rendered from the text they were written with, so a line never changes after
 * it appears: switching the encoder applies to the lines written next, not to
 * the ones already on screen.
 */
export type TerminalLineEncoder = TerminalTextEncoder | TerminalBinaryEncoder

/**
 * Text based lines: the bytes are decoded and split on the line breaks they
 * contain, which stay in the line text so that concatenating the lines gives
 * the stream back.
 */
export interface TerminalTextEncoder {
  readonly kind: 'text'
  /**
   * Turns the bytes of a line into text. Defaults to UTF-8.
   */
  readonly encode?: (bytes: Uint8Array) => string
}

/**
 * Binary lines: a fixed amount of bytes per line, rendered once the line is
 * full, so a byte stream shows up as a stream of fixed length rows rather than
 * as lines split at whatever bytes happen to look like a line break.
 */
export interface TerminalBinaryEncoder {
  readonly kind: 'binary'
  /**
   * Amount of bytes a rendered line holds. Defaults to
   * {@link DEFAULT_BINARY_LINE_BYTES}.
   */
  readonly lineBytes?: number
  /**
   * Turns the bytes of a line into text. Receives a `DataView` over the chunk
   * the line was written from, so a hex dump needs no copy of the data.
   * Defaults to hex pairs.
   */
  readonly encode?: (bytes: Uint8Array, view: DataView) => string
}

export const DEFAULT_BINARY_LINE_BYTES = 16

const HEX_GROUP_SIZE = 8

const textDecoder = new TextDecoder()

function decodeTextLine(bytes: Uint8Array): string {
  return textDecoder.decode(bytes)
}

function decodeHexLine(bytes: Uint8Array, view: DataView): string {
  const parts: string[] = []

  for (let index = 0; index < bytes.length; index++) {
    if (index > 0) {
      parts.push(index % HEX_GROUP_SIZE === 0 ? '  ' : ' ')
    }
    parts.push(view.getUint8(index).toString(16).padStart(2, '0'))
  }

  return parts.join('')
}

/**
 * Renders bytes as UTF-8 text, one line per line break in the data.
 */
export const decodeText: TerminalTextEncoder = {
  kind: 'text',
  encode: decodeTextLine,
}

/**
 * Renders bytes as hex pairs, one line per {@link DEFAULT_BINARY_LINE_BYTES}
 * bytes, e.g. `47 50 52 4d  43 2c 2c 56 20 76 65 72  73 75 73`.
 */
export const decodeHex: TerminalBinaryEncoder = {
  kind: 'binary',
  lineBytes: DEFAULT_BINARY_LINE_BYTES,
  encode: decodeHexLine,
}

import type { MaybeRefOrGetter, Stoppable } from '@vueuse/core'
import type { Ref } from 'vue'
import { tryOnScopeDispose, watchImmediate } from '@vueuse/core'
import { computed, shallowRef, toRaw, toValue } from 'vue'

/**
 * Anything that can hold a stream lock, i.e. a stream reader or writer.
 */
export interface StreamLockHandle {
  releaseLock: () => void
}

export interface UseStreamLockReturn<THandle extends StreamLockHandle> extends Stoppable {
  /**
   * The currently attached handle. Writable so callers can report failures
   * against the exact handle that produced them; public composables wrap this
   * in `readonly()`.
   */
  readonly handle: Ref<THandle | undefined>
  readonly isPending: Readonly<Ref<boolean>>
  readonly error: Ref<Error | undefined>
}

/**
 * Shared attachment lifecycle for a stream and one of its lock handles.
 *
 * `useTerminalReader` and `useTerminalWriter` differ only in which stream they
 * attach to and what they do with the handle afterwards (read a loop, write
 * chunks), so the attach/detach bookkeeping lives here once.
 *
 * @param stream the stream to hold a lock on, or a getter for it
 * @param attach takes a lock on the stream, e.g. `stream => stream.getReader()`.
 * Receives the raw stream, never a reactive wrapper around one.
 */
export function useStreamLock<TStream, THandle extends StreamLockHandle>(
  stream: MaybeRefOrGetter<TStream | null | undefined>,
  attach: (stream: TStream) => THandle,
): UseStreamLockReturn<THandle> {
  const handle = shallowRef<THandle>()
  const error = shallowRef<Error>()
  const isPending = computed(() => {
    return !!handle.value
  })

  // A handle can be released both here and by the watcher below, and
  // `releaseLock()` throws once a handle is no longer attached to its stream.
  const releasedHandles = new WeakSet<THandle & object>()

  function release(target: THandle | undefined) {
    if (!target || releasedHandles.has(target))
      return

    releasedHandles.add(target)
    target.releaseLock()
  }

  function start() {
    // Released up front rather than left to the watcher below: whoever switched
    // streams may close the previous one as soon as this returns, and a locked
    // stream rejects `cancel()`/`close()`.
    release(handle.value)

    try {
      const current = toValue(stream)

      // Normalised before it reaches `attach`. Vue never proxies a native
      // ReadableStream/WritableStream (they are host objects, so it passes them
      // through untouched and this is a no-op), but it does proxy stream-likes
      // that look like plain objects, and `attach` should get the stream itself
      // rather than a reactive wrapper that reads back as `this` inside
      // `getReader()`/`getWriter()`.
      handle.value = current == null ? void 0 : attach(toRaw(current))
    }
    catch (cause) {
      handle.value = void 0
      error.value = cause as Error
      throw cause
    }
    error.value = void 0
  }

  function stop() {
    // Detaches the handle and drops its lock right away, so the caller can tear
    // the stream down without waiting for a flush. Closing or cancelling the
    // stream itself stays the responsibility of whoever owns it.
    release(handle.value)
    handle.value = void 0
  }

  watchImmediate(() => toValue(stream), () => {
    start()
  })

  tryOnScopeDispose(() => {
    stop()
  })

  // Replacing the handle in `start()` still has to give the old lock back.
  watchImmediate(handle, (_, oldHandle) => {
    release(oldHandle)
  })

  return {
    handle,
    isPending,
    error,
    start,
    stop,
  }
}

import type { MaybeRefOrGetter, Stoppable } from '@vueuse/core'
import type { Ref } from 'vue'
import type { UseStreamLockReturn } from './useStreamLock'
import { readonly } from 'vue'
import { useStreamLock } from './useStreamLock'

export interface UseTerminalWriterOptions { }
export interface UseTerminalWriterReturn<T> extends Stoppable {
  write: (chunk: T) => Promise<void>
  isPending: Readonly<Ref<boolean>>
  error: Readonly<Ref<Error | null | undefined>>
}

export function useTerminalWriter<T>(
  writable: MaybeRefOrGetter<WritableStream<T> | null | undefined>,
): UseTerminalWriterReturn<T> {
  const {
    handle: writer,
    error,
    isPending,
    start,
    stop,
  }: UseStreamLockReturn<WritableStreamDefaultWriter<T>> = useStreamLock(
    writable,
    stream => stream.getWriter(),
  )

  async function write(chunk: T) {
    const current = writer.value

    if (!current)
      return

    try {
      await current.write(chunk)
    }
    catch (cause) {
      // A released writer (target switched mid-write) rejects the pending
      // write. That is teardown, not a failure of the target, so it neither
      // lands in `error` nor rejects into the caller. Closing the sink stays
      // the responsibility of the target itself.
      if (writer.value !== current)
        return

      const e = cause instanceof Error
        ? cause
        : new Error('Unable to write', { cause })

      error.value = e

      throw e
    }
  }

  return {
    isPending,
    error: readonly(error),
    stop,
    start,
    write,
  }
}

import type { MaybeRefOrGetter, Stoppable } from '@vueuse/core'
import type { Ref } from 'vue'
import type { UseStreamLockReturn } from './useStreamLock'
import { watchImmediate } from '@vueuse/core'
import { readonly } from 'vue'
import { useStreamLock } from './useStreamLock'

export interface UseTerminalReaderOptions<T> {
  onRead?: (data: T) => Promise<void> | void
}

export interface UseTerminalReaderReturn extends Stoppable {
  isPending: Readonly<Ref<boolean>>
  error: Readonly<Ref<Error | null | undefined>>
}

export function useTerminalReader<T>(
  readable: MaybeRefOrGetter<ReadableStream<T> | null | undefined>,
  options?: UseTerminalReaderOptions<T>,
): UseTerminalReaderReturn {
  const {
    handle: reader,
    error,
    isPending,
    start,
    stop,
  }: UseStreamLockReturn<ReadableStreamDefaultReader<T>> = useStreamLock(
    readable,
    stream => stream.getReader(),
  )

  watchImmediate(reader, async (activeReader) => {
    const onRead = options?.onRead

    if (!activeReader || !onRead)
      return

    try {
      await readLoop(activeReader, onRead)
    }
    catch (cause) {
      // Releasing the lock on a stopped or replaced reader rejects the pending
      // read. That is teardown, not a failure of the target, so it stays out
      // of `error`.
      if (reader.value !== activeReader)
        return
      error.value = cause as Error
    }
    finally {
      if (reader.value === activeReader)
        stop()
    }
  })

  return {
    isPending,
    error: readonly(error),
    start,
    stop,
  }
}

async function readLoop<T>(
  reader: ReadableStreamDefaultReader<T>,
  onRead: (data: T) => Promise<void> | void,
) {
  while (true) {
    const result = await reader.read()
    if (result.value) {
      await onRead(result.value)
    }
    if (result.done) {
      break
    }
  }
}

import type { MaybeRef, MaybeRefOrGetter, Ref } from 'vue'
import type { TerminalLineEncoder } from './encoders'
import { computed, readonly, ref, shallowRef, toValue, unref } from 'vue'
import { decodeHex, decodeText, DEFAULT_BINARY_LINE_BYTES } from './encoders'

const DEFAULT_MAX_BYTES = 256 * 1024
const DEFAULT_MAX_LINE_BYTES = 1024

const CARRIAGE_RETURN = 0x0D
const LINE_FEED = 0x0A

const EMPTY_BYTES = new Uint8Array(0)

const textEncoder = new TextEncoder()

export interface UseTerminalOutputOptions {
  initialEntries?: MaybeRefOrGetter<Iterable<TerminalLineSeed>>
  /**
   * Maximum amount of content bytes kept in the buffer at once.
   * Oldest lines are dropped first once the limit is exceeded.
   */
  maxBytes?: MaybeRefOrGetter<number>
  /**
   * Maximum amount of content bytes a single line is allowed to hold.
   * Bytes written past that limit are dropped from the end of the line.
   */
  maxLineBytes?: MaybeRefOrGetter<number>
  /**
   * How bytes become the text a line renders, and how they are grouped into
   * lines in the first place. Defaults to {@link decodeText}.
   *
   * A ref rather than a getter: the encoder is itself a value, which `toValue()`
   * would call instead of reading.
   */
  encode?: MaybeRef<TerminalLineEncoder>
  onTruncate?: (bytes: number | bigint) => void
}

export interface UseTerminalOutputReturn {
  entries: Readonly<Ref<Iterable<TerminalLineEntry>>>
  /**
   * Amount of content bytes currently kept in the buffer, including the bytes
   * of a binary line that has not been rendered yet.
   */
  sizeBytes: Readonly<Ref<number | bigint>>
  /**
   * Amount of content bytes dropped since the last `clear()` call.
   */
  truncatedBytes: Readonly<Ref<number | bigint>>
  /**
   * Appends `data` to the buffer, grouped into lines by the active encoder.
   * Text is encoded into bytes first, so lines the terminal itself produces
   * share the buffer with device output.
   */
  append: (data: Uint8Array | string, type: TerminalLineEntryType) => void
  clear: () => void
}

export type TerminalLineEntryType = 'input' | 'output' | 'system'

/**
 * A line the buffer starts with, rendered as a single line whatever the active
 * encoder does with a stream.
 */
export interface TerminalLineSeed {
  readonly type: TerminalLineEntryType
  readonly content?: Uint8Array | string
}

export interface TerminalLineEntry {
  readonly id: string
  readonly type: TerminalLineEntryType
  /**
   * Bytes of this line, as they were received: views over the incoming chunks
   * rather than copies of them.
   */
  readonly bytes: Uint8Array
  /**
   * Text of this line, written once and never rewritten.
   *
   * A text line keeps the break that ended it, so concatenating the lines of
   * the buffer gives the stream back, which is what copying the output uses.
   */
  readonly content: string
  /**
   * Amount of content bytes kept for this line.
   */
  readonly byteLength?: number | bigint
  /**
   * Amount of content bytes dropped from the end of this line.
   */
  readonly droppedBytes?: number | bigint
}

interface TerminalLineState {
  id: string
  type: TerminalLineEntryType
  bytes: Uint8Array
  content: string
  byteLength: number | bigint
  droppedBytes: number | bigint
}

/**
 * Half-open slice of a chunk holding one line, break included, plus the index
 * the next line starts at.
 */
interface LineSegment {
  start: number
  end: number
  next: number
}

export function useTerminalOutput(options?: UseTerminalOutputOptions): UseTerminalOutputReturn {
  const entries = ref<TerminalLineEntry[]>([])
  const sizeBytes = shallowRef<number | bigint>(0)
  const truncatedBytes = shallowRef<number | bigint>(0)

  const maxBytes = computed(() => Math.max(0, toValue(options?.maxBytes) ?? DEFAULT_MAX_BYTES))
  const maxLineBytes = computed(() => Math.max(0, toValue(options?.maxLineBytes) ?? DEFAULT_MAX_LINE_BYTES))
  const onTruncate = options?.onTruncate

  // The encoder is read on write, never on read: a line is rendered as it is
  // written and stays as it is, so switching the encoder changes what the lines
  // written next look like and leaves the ones on screen untouched.
  let encoding: TerminalLineEncoder = unref(options?.encode) ?? decodeText

  // Bytes of the binary line currently being filled in. They are accounted for
  // from the moment they arrive, but a binary line is only rendered once it
  // holds its full length.
  let pending: Uint8Array = EMPTY_BYTES

  function render(bytes: Uint8Array): string {
    if (encoding.kind === 'binary') {
      const encode = encoding.encode ?? decodeHex.encode!

      // A view over the chunk the line was written from, so rendering a hex
      // dump needs no copy of the data.
      return encode(bytes, new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength))
    }

    const encode = encoding.encode ?? decodeText.encode!

    return encode(bytes)
  }

  /**
   * Bytes a rendered binary line holds, for a binary encoder.
   *
   * Never longer than `maxLineBytes`, so a full line always fits the buffer and
   * none of its bytes count as dropped.
   */
  function binaryLineBytes(): number {
    if (encoding.kind !== 'binary')
      return maxLineBytes.value

    const lineBytes = encoding.lineBytes ?? DEFAULT_BINARY_LINE_BYTES

    return Math.max(1, Math.min(lineBytes, maxLineBytes.value))
  }

  function drop(line: TerminalLineState, bytes: number | bigint) {
    if (bytes <= 0)
      return
    line.droppedBytes = sumOf(line.droppedBytes, bytes)
    truncatedBytes.value = sumOf(truncatedBytes.value, bytes)
    onTruncate?.(bytes)
  }

  function sumOf(value: number | bigint, other: number | bigint): number | bigint {
    if (isBigint(value) || isBigint(other)) {
      return BigInt(value) + BigInt(other)
    }
    return value + other
  }

  function differenceOf(value: number | bigint, other: number | bigint): number | bigint {
    if (isBigint(value) || isBigint(other)) {
      return BigInt(value) - BigInt(other)
    }
    return value - other
  }

  function isBigint(value: number | bigint): value is bigint {
    return typeof value === 'bigint'
  }

  /**
   * Fits `segment` into the room left on `line` and accounts for it. Returns the
   * part of the segment that made it into the buffer.
   */
  function reserve(line: TerminalLineState, bytes: Uint8Array, segment: LineSegment): Uint8Array | undefined {
    const length = segment.end - segment.start
    if (length <= 0)
      return

    let available = differenceOf(maxLineBytes.value, line.byteLength)
    if (available > Number.MAX_SAFE_INTEGER) {
      available = Number.MAX_SAFE_INTEGER
    }
    else {
      available = Number(available)
    }

    if (available <= 0) {
      // The line is already at its limit: its first bytes are the ones being
      // kept and everything written after them is dropped.
      drop(line, length)
      return
    }

    const keptLength = Math.min(length, available)

    line.byteLength = sumOf(line.byteLength, keptLength)
    sizeBytes.value = sumOf(sizeBytes.value, keptLength)
    drop(line, length - keptLength)

    return bytes.subarray(segment.start, segment.start + keptLength)
  }

  function createLine(type: TerminalLineEntryType, bytes: Uint8Array, segment: LineSegment): TerminalLineState {
    const line: TerminalLineState = {
      id: createId(),
      type,
      bytes: EMPTY_BYTES,
      content: '',
      byteLength: 0,
      droppedBytes: 0,
    }

    const kept = reserve(line, bytes, segment)

    if (kept) {
      line.bytes = kept
      line.content = render(kept)
    }

    return line
  }

  function writeText(entry: TerminalLineEntry, bytes: Uint8Array, segment: LineSegment) {
    const line = asState(entry)
    const kept = reserve(line, bytes, segment)
    if (!kept)
      return

    line.content += render(kept)
    line.bytes = merge(line.bytes, kept)
  }

  function appendText(bytes: Uint8Array, type: TerminalLineEntryType) {
    const list = entries.value
    let index = 0

    // Content that does not start with a line break continues the last line,
    // which is what makes a device writing without a trailing newline still
    // fill the line it is on.
    if (list.length > 0) {
      const segment = readSegment(bytes, 0)
      writeText(list[list.length - 1]!, bytes, segment)
      index = segment.next
    }

    while (index < bytes.length) {
      const segment = readSegment(bytes, index)
      list.push(createLine(type, bytes, segment))
      index = segment.next
    }

    evict()
  }

  function appendBinary(bytes: Uint8Array, type: TerminalLineEntryType) {
    const list = entries.value
    const lineBytes = binaryLineBytes()
    let line: Uint8Array = pending
    let index = 0

    // Counted as they arrive: these bytes are held by the buffer whether they
    // fill a line now or the next one.
    sizeBytes.value = sumOf(sizeBytes.value, bytes.length)

    while (index < bytes.length) {
      const kept = Math.min(lineBytes - line.length, bytes.length - index)
      line = merge(line, bytes.subarray(index, index + kept))
      index += kept

      // A line is rendered once it overflows, and only then.
      if (line.length < lineBytes)
        break

      list.push({
        id: createId(),
        type,
        bytes: line,
        content: render(line),
        byteLength: line.length,
        droppedBytes: 0,
      })

      line = EMPTY_BYTES
    }

    pending = line

    evict()
  }

  function dropPending() {
    if (!pending.length)
      return

    // The bytes of a line that was never rendered would be split by the next
    // encoder differently than the binary one did, so they cannot be kept.
    truncatedBytes.value = sumOf(truncatedBytes.value, pending.length)
    sizeBytes.value = differenceOf(sizeBytes.value, pending.length)
    onTruncate?.(pending.length)
    pending = EMPTY_BYTES
  }

  function evict() {
    const list = entries.value
    const limit = maxBytes.value

    // The line currently being written to is always kept, `maxLineBytes` is the
    // hard ceiling for it.
    if (sizeBytes.value <= limit || list.length <= 1)
      return

    let count = 0
    let remaining: number | bigint = sizeBytes.value

    while (count < list.length - 1 && remaining > limit) {
      remaining = differenceOf(remaining, asState(list[count]!).byteLength)
      count++
    }

    for (const entry of list.splice(0, count)) {
      const line = asState(entry)
      sizeBytes.value = differenceOf(sizeBytes.value, line.byteLength)
      drop(line, line.byteLength)
    }
  }

  function append(data: Uint8Array | string, type: TerminalLineEntryType) {
    const bytes = toBytes(data)
    if (!bytes.length)
      return

    const next = unref(options?.encode) ?? decodeText

    if (next !== encoding) {
      encoding = next
      dropPending()
    }

    if (encoding.kind === 'binary')
      appendBinary(bytes, type)
    else
      appendText(bytes, type)
  }

  function clear() {
    pending = EMPTY_BYTES
    entries.value = []
    sizeBytes.value = 0
    truncatedBytes.value = 0
  }

  const initialEntries = toValue(options?.initialEntries)

  if (initialEntries) {
    for (const entry of initialEntries) {
      const bytes = toBytes(entry.content)
      const segment = { start: 0, end: bytes.length, next: bytes.length }
      entries.value.push(createLine(entry.type, bytes, segment))
    }
    evict()
  }

  return {
    entries: readonly(entries),
    sizeBytes: readonly(sizeBytes),
    truncatedBytes: readonly(truncatedBytes),
    append,
    clear,
  }
}

/**
 * Locates the line starting at `from`: the bytes up to and including the next
 * line break, and where the following line starts.
 *
 * `\r\n` counts as a single break and a lone `\r` ends a line on its own, the
 * way a terminal treats the input it receives. Only `\r` and `\n` can split a
 * line, and neither is a byte of a multi-byte UTF-8 sequence, so a line is
 * always cut between characters.
 */
function readSegment(bytes: Uint8Array, from: number): LineSegment {
  for (let index = from; index < bytes.length; index++) {
    const byte = bytes[index]!

    if (byte === LINE_FEED)
      return { start: from, end: index + 1, next: index + 1 }

    if (byte === CARRIAGE_RETURN) {
      const next = bytes[index + 1] === LINE_FEED ? index + 2 : index + 1

      return { start: from, end: next, next }
    }
  }

  return { start: from, end: bytes.length, next: bytes.length }
}

function toBytes(data: Uint8Array | string | undefined): Uint8Array {
  if (typeof data === 'string')
    return textEncoder.encode(data)

  return data ?? EMPTY_BYTES
}

/**
 * Concatenates `chunk` onto `base`, reusing either side when there is nothing
 * to merge.
 */
function merge(base: Uint8Array, chunk: Uint8Array): Uint8Array {
  if (!base.length)
    return chunk

  if (!chunk.length)
    return base

  const merged = new Uint8Array(base.length + chunk.length)
  merged.set(base, 0)
  merged.set(chunk, base.length)

  return merged
}

function asState(entry: TerminalLineEntry): TerminalLineState {
  return entry as unknown as TerminalLineState
}

function createTimestampId(exponent: number = 0) {
  const now = Date.now()
  const div = 10 ** exponent
  const timestamp = div > 1
    ? Math.floor(now / div) * div
    : now
  return timestamp.toString(36)
}

function createRandomId() {
  return Math.random().toString(36).slice(2)
}

function createId(): string {
  return `${createTimestampId()}-${createRandomId()}`
}

import type { Stoppable } from '@vueuse/core'
import type { MaybeRefOrGetter, Ref } from 'vue'
import type { UseTerminalReaderOptions } from './useTerminalReader'
import type { UseTerminalWriterOptions } from './useTerminalWriter'
import { notNullish, tryOnScopeDispose } from '@vueuse/core'
import { computed, toValue } from 'vue'
import { useTerminalReader } from './useTerminalReader'
import { useTerminalWriter } from './useTerminalWriter'

export interface UseSerialTerminalOptions extends UseTerminalReaderOptions<Uint8Array>, UseTerminalWriterOptions {}
export interface UseSerialTerminalReturn extends Stoppable {
  write: (chunk: Uint8Array) => Promise<void>
  stop: () => void
  readonly errors: Readonly<Ref<readonly Error[]>>
}

export interface SerialTerminalTarget {
  readable?: ReadableStream<Uint8Array> | null
  writable?: WritableStream<Uint8Array> | null
}

export function useSerialTerminal(
  target: MaybeRefOrGetter<SerialTerminalTarget | null | undefined>,
  options?: UseSerialTerminalOptions,
): UseSerialTerminalReturn {
  const readable = () => toValue(target)?.readable
  const {
    isPending: isReaderPending,
    error: readerError,
    start: startReader,
    stop: stopReader,
  } = useTerminalReader(readable, {
    onRead: options?.onRead,
  })

  const writable = () => toValue(target)?.writable
  const {
    isPending: isWriterPending,
    error: writerError,
    start: startWriter,
    stop: stopWriter,
    write,
  } = useTerminalWriter(writable)

  const isPending = computed(() => {
    return isReaderPending.value && isWriterPending.value
  })

  function start() {
    startReader()
    startWriter()
  }

  function stop() {
    stopReader()
    stopWriter()
  }

  tryOnScopeDispose(() => {
    stop()
  })

  const errors = computed(() => {
    return [
      readerError.value,
      writerError.value,
    ].filter(notNullish)
  })

  return {
    isPending,
    errors,
    write,
    start,
    stop,
  }
}
